script.setup:
// poisson-disk-sampling places points one at a time, never closer than a distance that varies
// over the canvas (a ripple pattern here); each point becomes a dot sized to its spacing.
const mod = await ctx.utils.import("https://esm.sh/poisson-disk-sampling@2.3.1");
const PoissonDiskSampling = mod.default ?? mod;
const gl = ctx.gl;
const H = 100;
const s = ctx.state;
s.start = (cx, cy) => {
  const [w, h] = ctx.resolution, W = H * w / h;
  const u = ctx.uniforms, phase = Math.random() * 6.283;
  // 0 → densest, 1 → sparsest: rings around (cx, cy) bent by a slow wave.
  const density = (p) => {
    const d = Math.hypot(p[0] - cx, p[1] - cy);
    return Math.pow(0.5 + 0.5 * Math.sin(d * u.u_rings * 0.06 + Math.sin(p[0] * 0.05 + phase) * 1.2 - phase), 1.5);
  };
  s.pds = new PoissonDiskSampling({ shape: [W, H], minDistance: u.u_min, maxDistance: u.u_min * u.u_ratio, tries: 20, distanceFunction: density });
  s.pds.addPoint([cx, cy]);
  s.density = density; s.W = W; s.cx = cx; s.cy = cy;
  s.count = 0; s.data = new Float32Array(4 * 40000); s.done = 0;
};
s.prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec4 a_point; // x, y, spacing, birth time
uniform vec2 u_scale; uniform float u_now; uniform float u_px;
out float v_age; out float v_f;
void main(){
  v_age = u_now - a_point.w; v_f = a_point.z;
  gl_Position = vec4(a_point.xy * u_scale - 1.0, 0.0, 1.0);
  float grow = smoothstep(0.0, 0.35, v_age);
  gl_PointSize = a_point.z * u_px * grow;
}`, `#version 300 es
precision highp float; in float v_age; in float v_f; out vec4 outColor;
uniform vec3 u_dense; uniform vec3 u_sparse; uniform float u_maxf;
void main(){
  float d = length(gl_PointCoord - 0.5) * 2.0;
  float a = 1.0 - smoothstep(0.74, 0.82, d);
  if (a <= 0.0) discard;
  vec3 c = mix(u_dense, u_sparse, clamp(v_f / u_maxf, 0.0, 1.0));
  c += vec3(1.0, 0.9, 0.7) * exp(-v_age * 4.0) * 0.8; // fresh points flash
  outColor = vec4(c * a, 1.0);
}`);
s.vao = gl.createVertexArray(); s.buf = gl.createBuffer();
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buf);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 4, gl.FLOAT, false, 16, 0);
gl.bindVertexArray(null);
const [w, h] = ctx.resolution;
s.start(H * w / h * 0.5, H * 0.5);
s.wasDown = false;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const [w, h] = ctx.resolution;
// Click to restart the sampling around the pointer; the reset button restarts at the center.
const click = ctx.mouseDown && !s.wasDown;
s.wasDown = ctx.mouseDown;
if (click) s.start(ctx.mouse[0] * s.W, (1 - ctx.mouse[1]) * 100);
else if (u.u_reset || Math.abs(s.W - 100 * w / h) > 0.5) s.start(50 * w / h, 50);
// Grow the set a few points per frame so the fill is visible.
let added = 0;
while (added < u.u_rate && s.count < 40000) {
  const p = s.pds.next();
  if (!p) break;
  const f = u.u_min + (u.u_min * u.u_ratio - u.u_min) * s.density(p);
  s.data.set([p[0], p[1], f, ctx.time], s.count * 4);
  s.count++; added++;
}
if (!added) s.done += ctx.dt;
// Once full, wait, then start again around a drifting center.
if (s.done > 3 && u.u_loop) s.start(s.W * (0.3 + 0.4 * Math.random()), 100 * (0.3 + 0.4 * Math.random()));
gl.clearColor(0.035, 0.035, 0.05, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_scale: [2 / s.W, 2 / 100], u_now: ctx.time, u_px: h / 100, u_dense: u.u_dense, u_sparse: u.u_sparse, u_maxf: u.u_min * u.u_ratio });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buf);
gl.bufferData(gl.ARRAY_BUFFER, s.data.subarray(0, s.count * 4), gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.count);
gl.bindVertexArray(null);
ctx.publish("points", s.count);
